import type { AgentNode, CodeGraph, Session } from './types'
import type { VaultGraph } from './obsidian/types'

export type NetworkKind = 'project' | 'agent' | 'worktree' | 'session' | 'code' | 'note'
export interface NetworkPoint { x: number; y: number; z: number }

// Projection helper generated by the configured local MinicPM model, then reviewed here.
export function projectPoint(p: NetworkPoint, yaw: number, pitch: number, zoom: number, width: number, height: number) {
  const x = p.x * Math.cos(yaw) + p.z * Math.sin(yaw)
  const z = -p.x * Math.sin(yaw) + p.z * Math.cos(yaw)
  const y = p.y * Math.cos(pitch) - z * Math.sin(pitch)
  const depth = p.y * Math.sin(pitch) + z * Math.cos(pitch)
  const scale = 900 / Math.max(200, 900 + depth) * zoom
  return { x: width / 2 + x * scale, y: height / 2 + y * scale, depth, scale }
}

export interface AgentNetworkNode extends NetworkPoint {
  id: string
  label: string
  kind: NetworkKind
  color: string
  radius: number
  detail: string
  agentId?: string
  notePath?: string
  galaxy?: boolean
}
export interface AgentNetworkEdge { from: string; to: string }
export interface AgentNetwork { nodes: AgentNetworkNode[]; edges: AgentNetworkEdge[]; totalCodeNodes: number }
export const LARGE_GALAXY_THRESHOLD = 400
export function spiralGalaxyPoint(id: string, index: number, count: number): NetworkPoint {
  const radius = 24 + Math.sqrt((index + .5) / Math.max(1, count)) * 350
  const angle = (index % 4) * Math.PI / 2 + radius * .016 + (hash(id + ':arm') - .5) * .5
  return { x: Math.cos(angle) * radius, y: Math.sin(angle) * radius, z: (hash(id + ':height') - .5) * (18 + 25 * (1 - radius / 380)) }
}

/** Two independently sourced galaxies; their separation never invents cross-source edges. */
export function combineNetworkUniverses(workspace: AgentNetwork, vault: AgentNetwork): AgentNetwork {
  const place = (nodes: AgentNetworkNode[], center: number, scale: number) => nodes.map((node) => ({ ...node, x: node.x * scale + center, y: node.y * scale, z: node.z * scale, radius: node.kind === 'project' ? 14 : node.radius }))
  return {
    nodes: [...place(workspace.nodes, -380, .5), ...place(vault.nodes, 380, .7).map((node) => node.id === 'vault' ? { ...node, label: 'Obsidian', radius: node.galaxy ? 6 : 14, color: node.galaxy ? '#f5dfff' : '#5eead4', detail: `${node.label} · ${node.detail}` } : node)],
    edges: [...workspace.edges, ...vault.edges], totalCodeNodes: workspace.totalCodeNodes,
  }
}
export function projectUniversePoint(node: AgentNetworkNode, yaw: number, pitch: number, zoom: number, width: number, height: number) {
  const center = node.id === 'vault' || node.notePath ? 380 : -380
  let projected
  if (node.galaxy) {
    const x = node.x - center, cosine = Math.cos(yaw), sine = Math.sin(yaw)
    const spinX = x * cosine - node.y * sine, spinY = x * sine + node.y * cosine
    const tilt = 1.04 + pitch * .5
    const tiltedY = spinY * Math.cos(tilt) - node.z * Math.sin(tilt)
    projected = projectPoint({ x: spinX * Math.cos(-.4) - tiltedY * Math.sin(-.4), y: spinX * Math.sin(-.4) + tiltedY * Math.cos(-.4), z: spinY * Math.sin(tilt) + node.z * Math.cos(tilt) }, 0, 0, zoom, width, height)
  } else projected = projectPoint({ ...node, x: node.x - center }, yaw, pitch, zoom, width, height)
  return { ...projected, x: projected.x + center * zoom }
}

export const NETWORK_COLORS = {
  project: '#d9b9ff', agent: '#a78bfa', worktree: '#34d399', session: '#fbbf24', code: '#38bdf8', note: '#a78bfa',
} satisfies Record<NetworkKind, string>
const CODE_COLORS = { module: '#a78bfa', file: '#38bdf8', class: '#34d399', function: '#ec4899', config: '#fbbf24' }

export function buildVaultNetwork(graph: VaultGraph): AgentNetwork {
  const galaxy = graph.notes.length >= LARGE_GALAXY_THRESHOLD
  const palette = ['#a78bfa', '#38bdf8', '#34d399', '#ec4899', '#fbbf24']
  const folders = [...new Set(graph.notes.map((note) => note.path.split('/').slice(0, 2).join('/')))].sort()
  const nodes: AgentNetworkNode[] = [{ id: 'vault', label: graph.name, kind: 'project', x: 0, y: 0, z: 0, radius: 12, color: NETWORK_COLORS.project, galaxy, detail: `${graph.notes.length} local Markdown notes · vault membership` }]
  const edges: AgentNetworkEdge[] = []
  for (const [index, note] of graph.notes.entries()) {
    const group = note.path.split('/').slice(0, 2).join('/'), cluster = folders.indexOf(group), angle = cluster * 2.3999632297
    const orbit = index * 2.3999632297 + hash(note.path) * 1.7, radius = 55 + Math.sqrt(hash(note.path + ':r')) * 170
    const position = galaxy ? spiralGalaxyPoint(note.path, index, graph.notes.length) : { x: Math.cos(angle) * 220 + Math.cos(orbit) * radius, y: Math.sin(angle) * 180 + Math.sin(orbit) * radius, z: (hash(note.path + ':z') - .5) * 420 }
    const starColor = ['#c4b5fd', '#93c5fd', '#f9a8d4', '#bfdbfe', '#e9d5ff'][index % 5]
    nodes.push({ id: `note:${note.path}`, label: note.title, kind: 'note', ...position, radius: galaxy ? 1.8 : 2.8, color: galaxy ? starColor : palette[cluster % palette.length], galaxy, detail: note.path, notePath: note.path })
  }
  const ids = new Set(nodes.map((node) => node.id))
  for (const link of graph.links) if (ids.has(`note:${link.from}`) && ids.has(`note:${link.to}`)) edges.push({ from: `note:${link.from}`, to: `note:${link.to}` })
  return { nodes, edges, totalCodeNodes: 0 }
}

function hash(text: string): number {
  let value = 2166136261
  for (let i = 0; i < text.length; i++) value = Math.imul(value ^ text.charCodeAt(i), 16777619)
  return (value >>> 0) / 4294967295
}

export interface WorkspaceTreeEntry { path: string; type: 'file' | 'dir' }

/** A file-tree graph: edges mean directory containment, not inferred code dependencies. */
export function workspaceTreeGraph(entries: WorkspaceTreeEntry[]): CodeGraph {
  const safe = entries.filter((entry) => entry.path.startsWith('src/') && !entry.path.split('/').includes('..'))
  const directories = [...new Set(['src', ...safe.filter((entry) => entry.type === 'dir').map((entry) => entry.path.replace(/\/$/, ''))])].sort()
  const all = [{ path: 'src', type: 'dir' as const }, ...safe]
  const ids = new Set(all.map((entry) => entry.path.replace(/\/$/, '')))
  const nodes = all.map((entry) => {
    const path = entry.path.replace(/\/$/, '')
    const parent = path.slice(0, path.lastIndexOf('/')) || 'src'
    const group = entry.type === 'dir' ? path : parent
    const index = Math.max(0, directories.indexOf(group))
    const angle = index * 2.399963229728653
    const radius = group === 'src' ? 0 : .13 + hash(group) * .22
    const offsetAngle = hash(path) * Math.PI * 2
    const offset = entry.type === 'dir' ? 0 : .025 + hash(`${path}:offset`) * .055
    return { id: path, label: path.split('/').pop() || path, type: entry.type === 'dir' ? 'module' as const : 'file' as const, cluster: group, x: .5 + Math.cos(angle) * radius + Math.cos(offsetAngle) * offset, y: .5 + Math.sin(angle) * radius + Math.sin(offsetAngle) * offset, size: entry.type === 'dir' ? 12 : 3 }
  })
  const edges = nodes.flatMap((node) => {
    const parent = node.id.slice(0, node.id.lastIndexOf('/'))
    return parent && ids.has(parent) ? [{ from: parent, to: node.id }] : []
  })
  return { repo: 'Project src tree', branch: '', semanticReady: false, renderMs: 0, nodeCount: nodes.length, edgeCount: edges.length, nodes, edges }
}

/** Build links only from stored hierarchy, worktree membership, session owners and code edges. */
export function buildAgentNetwork(project: string, agents: AgentNode[], sessions: Session[], graph: CodeGraph): AgentNetwork {
  const nodes: AgentNetworkNode[] = [{ id: 'project', label: project, kind: 'project', x: 0, y: 0, z: 0, color: NETWORK_COLORS.project, radius: 12, detail: 'Stored workspace snapshot' }]
  const edges: AgentNetworkEdge[] = []
  const flat: Array<{ agent: AgentNode; parent: string }> = []
  const visit = (items: AgentNode[], parent: string) => {
    for (const agent of items) { flat.push({ agent, parent }); visit(agent.children, `agent:${agent.id}`) }
  }
  visit(agents, 'project')
  const worktrees = new Map<string, AgentNetworkNode>()
  flat.forEach(({ agent, parent }, index) => {
    const angle = index * 2.399963229728653
    const radius = 205 + hash(agent.id) * 115
    const point = { x: Math.cos(angle) * radius, y: Math.sin(angle) * radius * .77, z: (hash(`${agent.id}:z`) - .5) * 300 }
    nodes.push({ id: `agent:${agent.id}`, label: agent.name.replace(/ Agent$/, ''), kind: 'agent', ...point, color: NETWORK_COLORS.agent, radius: 8, detail: `${agent.status} · ${agent.metrics.completion}% complete`, agentId: agent.id })
    edges.push({ from: parent, to: `agent:${agent.id}` })
    if (agent.worktree) {
      if (!worktrees.has(agent.worktree)) {
        const tree = { id: `worktree:${agent.worktree}`, label: agent.worktree, kind: 'worktree' as const, x: point.x + 32, y: point.y + 35, z: point.z - 36, color: NETWORK_COLORS.worktree, radius: 4.5, detail: 'Worktree named in the agent configuration' }
        worktrees.set(agent.worktree, tree); nodes.push(tree)
      }
      edges.push({ from: `agent:${agent.id}`, to: `worktree:${agent.worktree}` })
    }
  })
  for (const session of sessions) {
    const owner = nodes.find((node) => node.id === `agent:${session.agentId}`)
    const angle = hash(session.id) * Math.PI * 2
    nodes.push({ id: `session:${session.id}`, label: session.name, kind: 'session', x: (owner?.x ?? 0) + Math.cos(angle) * 62, y: (owner?.y ?? 0) + Math.sin(angle) * 62, z: (owner?.z ?? 0) + 45, color: NETWORK_COLORS.session, radius: 4.5, detail: `${session.stats.turns} recorded turns · ${session.model}` })
    if (owner) edges.push({ from: owner.id, to: `session:${session.id}` })
  }

  // Bound the rendering work; counts in the UI distinguish displayed nodes from the full snapshot.
  const code = [...graph.nodes].sort((a, b) => b.size - a.size || a.id.localeCompare(b.id)).slice(0, 480)
  for (const node of code) {
    const x = Number.isFinite(node.x) ? node.x : hash(node.id)
    const y = Number.isFinite(node.y) ? node.y : hash(`${node.id}:y`)
    const palette = ['#a78bfa', '#38bdf8', '#ec4899', '#34d399', '#fbbf24']
    const color = node.id.startsWith('src') ? palette[Math.min(palette.length - 1, Math.floor(hash(node.cluster) * palette.length))] : CODE_COLORS[node.type]
    nodes.push({ id: `code:${node.id}`, label: node.label, kind: 'code', x: (x - .5) * 1050, y: (y - .5) * 860, z: (hash(node.id) - .5) * 400, color, radius: Math.max(2, Math.min(6, 2 + node.size * .22)), detail: node.id.startsWith('src') ? `${node.id} · project file tree` : `${node.type} · ${node.cluster} · stored code graph` })
    if (node.type === 'module') edges.push({ from: 'project', to: `code:${node.id}` })
  }
  const ids = new Set(nodes.map((node) => node.id))
  for (const edge of graph.edges) if (ids.has(`code:${edge.from}`) && ids.has(`code:${edge.to}`)) edges.push({ from: `code:${edge.from}`, to: `code:${edge.to}` })
  return { nodes, edges, totalCodeNodes: graph.nodes.length }
}
